import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("AssetInventory");
    private Connection dbConn;

    @Override
    public void init() throws ServletException {
        try {
            String dbUrl = System.getenv("INVENTORY_DB_URL");
            String dbUser = System.getenv("INVENTORY_DB_USER");
            String dbPass = System.getenv("INVENTORY_DB_PASS");
            Class.forName("org.postgresql.Driver");
            dbConn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
        } catch (Exception e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Input normalization - strip obvious attack patterns
        if (assetType != null) assetType = assetType.replaceAll("[;--]", "");
        if (department != null) department = department.replaceAll("[;--]", "");

        // Build parameterized base query
        StringBuilder query = new StringBuilder(
            "SELECT asset_id, asset_name, asset_type, department, purchase_date, value "
            + "FROM inventory WHERE 1=1");

        if (assetType != null && !assetType.isEmpty()) {
            query.append(" AND asset_type = ?");
        }
        if (department != null && !department.isEmpty()) {
            query.append(" AND department = ?");
        }

        // Dynamic ORDER BY - validated against allowlist
        String[] allowedCols = {"asset_id", "asset_name", "asset_type", "department", "purchase_date", "value"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equalsIgnoreCase(sortCol)) { validSort = true; break; }
            }
        }
        if (validSort) {
            query.append(" ORDER BY ").append(sortCol);
            if ("desc".equalsIgnoreCase(direction)) {
                query.append(" DESC");
            } else {
                query.append(" ASC");
            }
        }

        // Reporting filter - allows complex expressions for power users
        String filter = req.getParameter("filter");
        if (filter != null && !filter.isEmpty()) {
            // Sanitize: remove semicolons, block UNION keyword
            filter = filter.replace(";", "");
            if (!filter.toUpperCase().contains("UNION")) {
                query.append(" AND (").append(filter).append(")");
            }
        }

        try {
            PreparedStatement stmt = dbConn.prepareStatement(query.toString());
            int paramIdx = 1;
            if (assetType != null && !assetType.isEmpty()) {
                stmt.setString(paramIdx++, assetType);
            }
            if (department != null && !department.isEmpty()) {
                stmt.setString(paramIdx++, department);
            }

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getString("asset_id"));
                row.put("name", rs.getString("asset_name"));
                row.put("type", rs.getString("asset_type"));
                row.put("dept", rs.getString("department"));
                row.put("purchased", rs.getString("purchase_date"));
                row.put("value", rs.getDouble("value"));
                results.put(row);
            }
            rs.close();
            stmt.close();

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            log.warning("Query error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    public void destroy() {
        try { if (dbConn != null) dbConn.close(); } catch (SQLException ignored) {}
    }
}
